"""
    Return the path of the field in a dict.
    Arguments:
        item (dict): The object where we want to put a field.
        path (unicode): The path separated with dots to the field.
        default: default value if path not found.
    Return:
        The value.
    """
def json_get(item: Any, path: Any, `default: Any = None) -> object {
    tab = path.split(".");
    if (tab[0] in item) {
        if (len(tab) > 1) {
            return json_get(item[tab[0]], ".".join(tab[1:]), `default=`default);
        }
        return item[tab[0]];
    }
    return `default;
}

"""Remove suffix frm the end of s
    is s = "aaa.gpg" and suffix = ".gpg", return "aaa"
    if s is not a string return None
    if suffix is not a string, return s

    :param str s: string to modify
    :param str suffix: suffix to remove

    :rtype: Optional[str]=None
    """
def strip_suffix(s: Any, suffix: Any) -> object {
    if not isinstance(s, str) {
        return None;
    }
    if not isinstance(suffix, str) {
        return s;
    }
    if s.endswith(suffix) {
        return s[:-len(suffix)];
    }
    return s;
}

""" The weigher function.

    Must map nonnegative integers (zero representing the most important element) to a nonnegative weight.
    The default method, 'hyperbolic', provides hyperbolic weighing, that is, rank r is mapped to weight 1/(r+1)

    Args:
        r: Integer value (supposedly a rank) to weight
        method: Weighing method. 'hyperbolic'
    """
def weigher(r: Any, method: Any = 'hyperbolic') -> object {
    if (method == 'hyperbolic') {
        return (1 / (r + 1));
    } else {
        raise Exception('Unknown method: {}'.format(method));
    }
}

